<?php
namespace App\Controllers\Admin;
use App\Core\Controller;use App\Core\Auth;use App\Core\Database;use App\Core\Session;use App\Core\Audit;use App\Core\Upload;
final class PostAdminController extends Controller
{
 public function index():void{$u=Auth::requireAdmin();Auth::enforce('manage_content');$type=in_array($_GET['type']??'',['news','blog'],true)?$_GET['type']:'';$params=[];$where='1=1';if($type){$where='post_type=?';$params[]=$type;}$total=(int)(Database::one('SELECT COUNT(*) c FROM posts WHERE '.$where,$params)['c']??0);$p=admin_pager($total,15);$rows=Database::all('SELECT * FROM posts WHERE '.$where.' ORDER BY published_at DESC,id DESC LIMIT '.$p['per_page'].' OFFSET '.$p['offset'],$params);$this->view('admin/posts',['user'=>$u,'posts'=>$rows,'type'=>$type,'pagination'=>$p,'adminTitle'=>'News & Blog'],'admin');}
 public function save():void{$this->requirePost();$u=Auth::requireAdmin();Auth::enforce('manage_content');$id=(int)($_POST['id']??0);$title=substr(trim($_POST['title']??''),0,200);$type=in_array($_POST['post_type']??'news',['news','blog'],true)?$_POST['post_type']:'news';if(strlen($title)<3){Session::flash('error','Enter a valid post title.');redirect('admin/posts');}$img=null;try{if(isset($_FILES['featured_image'])&&($_FILES['featured_image']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE)$img=Upload::publicImage($_FILES['featured_image'],'posts');}catch(\Throwable $e){Session::flash('error',$e->getMessage());redirect('admin/posts');}$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$title),'-'));if($id){$old=Database::one('SELECT featured_image,slug FROM posts WHERE id=?',[$id]);$img=$img?:($old['featured_image']??null);$slug=$old['slug']??$slug;Database::exec('UPDATE posts SET post_type=?,title=?,excerpt=?,content=?,featured_image=?,status=?,is_featured=?,published_at=?,meta_title=?,meta_description=?,updated_by=? WHERE id=?',[$type,$title,substr(trim($_POST['excerpt']??''),0,800),substr(trim($_POST['content']??''),0,50000),$img,in_array($_POST['status']??'draft',['draft','published','archived'],true)?$_POST['status']:'draft',isset($_POST['is_featured'])?1:0,$_POST['published_at']?:date('Y-m-d H:i:s'),substr(trim($_POST['meta_title']??''),0,240),substr(trim($_POST['meta_description']??''),0,500),(int)$u['id'],$id]);}else{$base=$slug?:'post';$slug=$base.'-'.substr(bin2hex(random_bytes(3)),0,6);$id=Database::insert('INSERT INTO posts(post_type,title,slug,excerpt,content,featured_image,status,is_featured,published_at,meta_title,meta_description,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$type,$title,$slug,substr(trim($_POST['excerpt']??''),0,800),substr(trim($_POST['content']??''),0,50000),$img,in_array($_POST['status']??'draft',['draft','published','archived'],true)?$_POST['status']:'draft',isset($_POST['is_featured'])?1:0,$_POST['published_at']?:date('Y-m-d H:i:s'),substr(trim($_POST['meta_title']??''),0,240),substr(trim($_POST['meta_description']??''),0,500),(int)$u['id'],(int)$u['id']]);}Audit::write((int)$u['id'],'POST_SAVED','posts',$id,'News/blog post saved');Session::flash('success','Post saved.');redirect('admin/posts');}
 public function delete():void{$this->requirePost();$u=Auth::requireAdmin();Auth::enforce('manage_content');$id=(int)($_POST['id']??0);Database::exec('DELETE FROM posts WHERE id=?',[$id]);Audit::write((int)$u['id'],'DELETE','posts',$id,'Post deleted');Session::flash('success','Post deleted.');redirect('admin/posts');}
}
